function escapeText(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Input is the escaped receipt HTML generated by ReceiptView, with span/mark tags.
// Match visible text so searches can cross syntax-colouring tags, e.g. <%IFM001%>.
export function highlightReceiptSearch(html: string, query: string): { html: string; count: number } {
  if (!query) return { html, count: 0 };
  const entities: Record<string, string> = { amp: '&', lt: '<', gt: '>', nbsp: '\u00a0' };
  const parts = html.split(/(<[^>]+>)/g).map(part => ({
    tag: part.startsWith('<'),
    text: part.startsWith('<') ? part : part.replace(/&(amp|lt|gt|nbsp);/g, (_, name: string) => entities[name]),
  }));
  const text = parts.filter(part => !part.tag).map(part => part.text).join('');
  const pattern = new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
  const matches: Array<{ start: number; end: number }> = [];
  let match: RegExpExecArray | null;
  while ((match = pattern.exec(text)) !== null) {
    matches.push({ start: match.index, end: match.index + match[0].length });
  }
  if (!matches.length) return { html, count: 0 };

  let offset = 0;
  let matchIndex = 0;
  const highlighted = parts.map(part => {
    if (part.tag) return part.text;
    if (!part.text) return '';
    const end = offset + part.text.length;
    let localOffset = 0;
    let result = '';
    while (matchIndex < matches.length && matches[matchIndex].start < end) {
      const current = matches[matchIndex];
      const startInPart = Math.max(0, current.start - offset);
      const endInPart = Math.min(part.text.length, current.end - offset);
      result += escapeText(part.text.slice(localOffset, startInPart));
      result += `<mark class="receipt-search-match" data-receipt-search-index="${matchIndex}">${escapeText(part.text.slice(startInPart, endInPart))}</mark>`;
      localOffset = endInPart;
      if (current.end > end) break;
      matchIndex += 1;
    }
    result += escapeText(part.text.slice(localOffset));
    offset = end;
    return result;
  }).join('');
  return { html: highlighted, count: matches.length };
}
